-- MySQL schema for the Road Safety app (12 related tables).
-- The app runs this automatically at start-up. You can also run it by hand in MySQL Workbench:
--   CREATE DATABASE roadsafety; USE roadsafety; then run this file.
CREATE TABLE IF NOT EXISTS locations(id INT AUTO_INCREMENT PRIMARY KEY, state VARCHAR(60), district VARCHAR(60), area VARCHAR(60), lat DOUBLE, lon DOUBLE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS junctions(id INT AUTO_INCREMENT PRIMARY KEY, location_id INT, name VARCHAR(100), lat DOUBLE, lon DOUBLE, FOREIGN KEY (location_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS traffic_records(id INT AUTO_INCREMENT PRIMARY KEY, junction_id INT, day_type VARCHAR(20), `hour` INT, avg_delay_min DOUBLE, FOREIGN KEY (junction_id) REFERENCES junctions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS weather_rules(id INT AUTO_INCREMENT PRIMARY KEY, weather VARCHAR(40) UNIQUE, avoid_prone INT, advice VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS route_options(id INT AUTO_INCREMENT PRIMARY KEY, location_id INT, route_name VARCHAR(100), via VARCHAR(100), is_main INT, waterlogging_prone INT, extra_minutes INT, FOREIGN KEY (location_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS police_stations(id INT AUTO_INCREMENT PRIMARY KEY, location_id INT, name VARCHAR(100), phone VARCHAR(20), FOREIGN KEY (location_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS alerts(id INT AUTO_INCREMENT PRIMARY KEY, junction_id INT, station_id INT, priority VARCHAR(10), message VARCHAR(500), status VARCHAR(20) DEFAULT 'Sent', created DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (junction_id) REFERENCES junctions(id), FOREIGN KEY (station_id) REFERENCES police_stations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS claims(id INT AUTO_INCREMENT PRIMARY KEY, junction_id INT, driver VARCHAR(80), day_type VARCHAR(20), start_hour INT, end_hour INT, claimed_delay_min DOUBLE, typical_delay_min DOUBLE, verdict VARCHAR(100), created DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (junction_id) REFERENCES junctions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS predictions(id INT AUTO_INCREMENT PRIMARY KEY, location_id INT NULL, inputs TEXT, severity INT, confidence DOUBLE, note VARCHAR(255) DEFAULT '', created DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (location_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS drivers(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80), phone VARCHAR(20), vehicle VARCHAR(30), location_id INT, FOREIGN KEY (location_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS incidents(id INT AUTO_INCREMENT PRIMARY KEY, junction_id INT, kind VARCHAR(20), description VARCHAR(500), reporter VARCHAR(80), status VARCHAR(20) DEFAULT 'Active', created DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (junction_id) REFERENCES junctions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS driver_messages(id INT AUTO_INCREMENT PRIMARY KEY, driver_id INT, incident_id INT, `text` VARCHAR(600), status VARCHAR(10) DEFAULT 'Unread', created DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (driver_id) REFERENCES drivers(id), FOREIGN KEY (incident_id) REFERENCES incidents(id)) ENGINE=InnoDB;
